+// ZERO MATCHING ELEMENTS IS A SKIP — never a pass.
+func evaluateAttributeCheck(doc *goquery.Document, ch criteriaCheck) attributeOutcome {
+	sel, err := cascadia.Compile(ch.Selector)
+	if err != nil {
+		return attrSkipf("criteria defect, not a page defect: selector %q does not compile (%v) — nothing was asserted", ch.Selector, err)
+	}
+	nodes := doc.FindMatcher(sel)
+	if count := nodes.Length(); count == 0 {
+		return attrSkipf("selector %q matched no elements in the served HTML — nothing was asserted (elements built client-side are Tier 4's claim, not a pass here)", ch.Selector)
+	}
+	switch ch.Type {
+	case "attribute_absent":  return evaluateAttributeAbsent(nodes, ch, count)
+	case "attribute_matches": return evaluateAttributeMatches(nodes, ch, count)
+	}
+}
+// attribute_absent: FAIL if any matched element carries any listed attribute.
+// attribute_matches: one attribute, against `matches` and/or `not_matches`;
+//   a MISSING attribute FAILS both forms — the conditionality these entries
+//   want ("the link, if there is one, is real") is carried by the SELECTOR,
+//   which matches nothing and skips at the guard above.
+// Every detail string carries the ELEMENT COUNT: it is the only thing that
+// distinguishes a real assertion from a vacuous one after the fact.

